const K={products:'bma_products_v2',sales:'bma_sales_v2',cash:'bma_cash_v2',customers:'bma_customers_v2',purchases:'bma_purchases_v2',moves:'bma_moves_v2',cfg:'bma_cfg_v2',holds:'bma_holds_v2'};
const $=id=>document.getElementById(id);
const uid=()=>{try{return crypto.randomUUID()}catch{return 'bma-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}};
const load=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){console.warn('No se pudo guardar',k,e)}};
const money=n=>`${cfg?.currency||'S/'} ${Number(n||0).toFixed(2)}`;
let products=load(K.products,[]), sales=load(K.sales,[]), cash=load(K.cash,[]), customers=load(K.customers,[]), purchases=load(K.purchases,[]), moves=load(K.moves,[]), cfg=load(K.cfg,{name:'BMA MINIMARKET',address:'',phone:'',currency:'S/'}), holds=load(K.holds,[]);
let cart=[], cat='Todos', editingProduct=null, cashAction='OPEN', stockAction='in';
const statePayload=()=>({products,sales,cash,customers,purchases,moves,cfg,holds,version:1});
const persist=()=>{saveAllLocal();localStorage.setItem('bma_cloud_updated_at',new Date().toISOString());scheduleCloudSync()};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function renderCats(){let cats=['Todos',...new Set(products.map(p=>p.category).filter(Boolean))];$('categories').innerHTML=cats.map(c=>`<button class="chip ${c===cat?'active':''}" onclick='setCat(${JSON.stringify(c)})'>${esc(c)}</button>`).join('')}
function setCat(c){cat=c;renderCats();renderProducts()}
function renderProducts(){let q=$('search').value.toLowerCase();$('products').innerHTML=products.filter(p=>(cat==='Todos'||p.category===cat)&&(p.name+' '+p.code+' '+p.category).toLowerCase().includes(q)).map(p=>`<button class="product" onclick="add('${p.id}')" ${p.stock<=0?'disabled':''}><b>${esc(p.name)}</b><small>${esc(p.category||'Sin categoría')} · Stock ${p.stock}</small><span class="pprice">${money(p.price)}</span></button>`).join('')||'<div class="empty">No hay productos.</div>'}
function cartItemData(x){if(x.free)return x;return products.find(p=>p.id===x.id)}
function add(id){let p=products.find(x=>x.id===id);if(!p)return;let x=cart.find(x=>x.id===id);if(p.stock<=0)return alert('Producto sin stock');if(x){if(x.qty<p.stock)x.qty=Math.min(p.stock,x.qty+1)}else cart.push({id,qty:1,free:false});renderCart()}
function change(id,d){let x=cart.find(x=>x.id===id);if(!x)return;if(x.free){x.qty=Math.max(0,x.qty+d)}else{let p=products.find(p=>p.id===id);if(!p)return;x.qty=Math.max(0,Math.min(p.stock,x.qty+d))}if(!x.qty)cart=cart.filter(y=>y!==x);renderCart()}
function changeQty(id,val){let x=cart.find(x=>x.id===id);if(!x)return;let q=Number(val);if(!Number.isFinite(q)||q<=0){cart=cart.filter(y=>y!==x);renderCart();return}if(x.free){x.qty=q}else{let p=products.find(p=>p.id===id);if(!p)return;x.qty=Math.min(p.stock,q)}renderCart()}
function totals(){let sub=cart.reduce((s,x)=>{let p=cartItemData(x);return s+(Number(p?.price)||0)*(Number(x.qty)||0)},0),raw=Number($('discountInput').value||0),disc=$('discountType').value==='percent'?sub*raw/100:Math.min(raw,sub);return{sub,disc,total:Math.max(0,sub-disc),units:cart.reduce((s,x)=>s+(Number(x.qty)||0),0)}}
function renderCart(){let t=totals();$('cart').innerHTML=cart.length?cart.map((x,i)=>{let p=cartItemData(x),unit=p?.unit||'Unidad',step=x.free||['Kg','Gramo','Litro','Metro'].includes(unit)?'0.001':'1';return `<div class="line"><div><b>${esc(p?.name||'Venta libre')}</b>${x.free?'<small class="free-tag">Venta libre · no afecta inventario</small>':''}<br>${money(p?.price||0)} × ${x.qty} ${esc(unit)}</div><div class="qty"><button onclick="change('${x.id||('free-'+i)}',-1)">−</button><input class="qty-input" type="number" min="0.001" step="${step}" value="${x.qty}" onchange="changeQtyByIndex(${i},this.value)"><button onclick="change('${x.id||('free-'+i)}',1)">＋</button></div></div>`}).join(''):'<div class="empty">Tu carrito está vacío.<br>Agrega productos para iniciar.</div>';$('subtotal').textContent=money(t.sub);$('discount').textContent=money(t.disc);$('total').textContent=money(t.total);$('payTotal').textContent=money(t.total)}
function changeQtyByIndex(i,val){let x=cart[i];if(!x)return;let q=Number(val);if(!(q>0)){cart.splice(i,1);renderCart();return}if(!x.free){let p=products.find(p=>p.id===x.id);if(!p)return;q=Math.min(p.stock,q)}x.qty=q;renderCart()}
function customerOptions(id=''){let opts='<option value="">Cliente mostrador</option>'+customers.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}${c.balance>0?' · debe '+money(c.balance):''}</option>`).join('');$('saleCustomer').innerHTML=opts;$('payCustomer').innerHTML=opts}
function renderProductTable(){let q=($('productSearch').value||'').toLowerCase();let rows=products.filter(p=>(p.name+' '+p.code+' '+p.category).toLowerCase().includes(q));$('countProducts').textContent=products.length;$('lowStock').textContent=products.filter(p=>p.stock<=p.min).length;$('inventoryValue').textContent=money(products.reduce((s,p)=>s+p.price*p.stock,0));$('productTable').innerHTML=`<div class="tablewrap"><table class="table"><thead><tr><th>Producto</th><th>Código</th><th>Categoría</th><th>Costo</th><th>Venta</th><th>Stock</th><th>Acciones</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.code)}</td><td>${esc(p.category)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td class="${p.stock<=p.min?'low':''}">${p.stock} ${esc(p.unit)}</td><td><button onclick="editProduct('${p.id}')">✏️</button> <button onclick="deleteProduct('${p.id}')">🗑️</button></td></tr>`).join('')}</tbody></table></div>`}
function renderInventory(){let units=products.reduce((s,p)=>s+Number(p.stock),0),cv=products.reduce((s,p)=>s+p.cost*p.stock,0);$('stockUnits').textContent=units;$('costValue').textContent=money(cv);$('minCount').textContent=products.filter(p=>p.stock<=p.min).length;$('movementTable').innerHTML=moves.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Costo</th><th>Motivo</th></tr></thead><tbody>${[...moves].reverse().map(m=>`<tr><td>${new Date(m.date).toLocaleString('es-PE')}</td><td>${esc(m.productName)}</td><td>${esc(m.type)}</td><td>${m.qty}</td><td>${money(m.cost)}</td><td>${esc(m.reason)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel">Sin movimientos de inventario.</div>'}
function migrateCreditData(){
  let changed=false;
  sales.forEach(s=>{
    if(s.method==='Crédito' && s.creditAmount==null){s.creditAmount=Number(s.total||0);changed=true}
    if(s.method==='Crédito' && !s.paymentBreakdown){s.paymentBreakdown={cash:0,digital:0,card:0,credit:Number(s.creditAmount||0)};changed=true}if(s.method==='Crédito'&&(s.cashAmount||s.digitalAmount)){s.cashAmount=0;s.digitalAmount=0;changed=true}
    if(s.method==='Crédito' && !s.creditDueDate)s.creditDueDate='';
  });
  cash.forEach(x=>{
    if(x.type==='CREDIT_PAYMENT'){
      if(!x.method)x.method='Efectivo';if(x.initial==null)x.initial=String(x.note||'').toLowerCase().includes('inicial');
      if(x.cashAmount==null)x.cashAmount=x.method==='Efectivo'?Number(x.amount||0):0;
      if(x.digitalAmount==null)x.digitalAmount=(x.method==='Yape / Plin'||x.method==='Tarjeta')?Number(x.amount||0):0;
      if(!x.paymentBreakdown)x.paymentBreakdown=x.method==='Efectivo'?{cash:Number(x.amount||0),digital:0,card:0}:{cash:0,digital:x.method==='Yape / Plin'?Number(x.amount||0):0,card:x.method==='Tarjeta'?Number(x.amount||0):0};
      changed=true;
    }
  });
  if(changed)persistLocalOnly();
}
function customerPayments(c){return cash.filter(x=>x.type==='CREDIT_PAYMENT'&&x.customerId===c.id).reduce((s,x)=>s+Number(x.amount||0),0)}
function customerCreditSales(c){return sales.filter(s=>s.method==='Crédito'&&s.customerId===c.id).reduce((s,x)=>s+Number(x.creditAmount!=null?x.creditAmount:x.total||0),0)}
function customerDebt(c){return Math.max(0,customerCreditSales(c)-customerPayments(c))}
function customerCreditHistory(c){let rows=[];sales.filter(s=>s.method==='Crédito'&&s.customerId===c.id).forEach(s=>{let due=Number(s.creditAmount!=null?s.creditAmount:s.total||0),paid=Number(s.total||0)-due;rows.push({date:s.date,type:'Venta a crédito',amount:due,detail:`${s.receipt||'Venta'} · crédito ${money(due)}${s.creditDueDate?' · vence '+new Date(s.creditDueDate+'T23:59:59').toLocaleDateString('es-PE'):''}`,id:s.id});if(paid>0)rows.push({date:s.date,type:'Abono inicial',amount:-paid,detail:`${s.receipt||'Venta'} · ${s.initialPaymentMethod||'Efectivo'}`,id:s.id+'-initial'})});cash.filter(x=>x.type==='CREDIT_PAYMENT'&&x.customerId===c.id&&!x.initial).forEach(x=>rows.push({date:x.date,type:'Abono',amount:-Number(x.amount||0),detail:`${x.note||'Abono'} · ${x.method||'Efectivo'}`,id:x.id}));return rows.sort((a,b)=>new Date(b.date)-new Date(a.date))}
function renderCustomers(){customers.forEach(c=>{c.balance=customerDebt(c)});let credit=customers.reduce((s,c)=>s+customerDebt(c),0);$('customerCount').textContent=customers.length;$('creditTotal').textContent=money(credit);$('creditCustomers').textContent=customers.filter(c=>customerDebt(c)>0).length;$('customerTable').innerHTML=`<div class="tablewrap"><table class="table"><thead><tr><th>Cliente</th><th>Documento</th><th>Teléfono</th><th>Límite</th><th>Debe</th><th>Disponible</th><th>Acciones</th></tr></thead><tbody>${customers.map(c=>{let debt=customerDebt(c),available=Math.max(0,Number(c.limit||0)-debt);return `<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.doc)}</td><td>${esc(c.phone)}</td><td>${Number(c.limit||0)?money(c.limit):'Sin límite'}</td><td class="${debt>0?'low':''}">${money(debt)}</td><td>${Number(c.limit||0)?money(available):'—'}</td><td><button onclick="viewCustomer('${c.id}')">Ver cuenta</button>${debt>0?` <button onclick="payCredit('${c.id}')">Abono</button>`:''} <button onclick="editCustomer('${c.id}')">✏️</button>${debt<=0?` <button onclick="deleteCustomer('${c.id}')">🗑️</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`}
function renderPurchases(){$('purchaseTable').innerHTML=purchases.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Fecha</th><th>Proveedor</th><th>Producto</th><th>Cantidad</th><th>Total</th></tr></thead><tbody>${[...purchases].reverse().map(p=>`<tr><td>${new Date(p.date).toLocaleString('es-PE')}</td><td>${esc(p.supplier)}</td><td>${esc(p.productName)}</td><td>${p.qty}</td><td>${money(p.total)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel">Todavía no hay compras.</div>'}
function renderSales(){let total=sales.reduce((s,x)=>s+x.total,0),profit=sales.reduce((s,x)=>s+x.profit,0);$('saleCount').textContent=sales.length;$('saleTotal').textContent=money(total);$('profitTotal').textContent=money(profit);$('salesTable').innerHTML=sales.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Fecha</th><th>Comprobante</th><th>Pago</th><th>Cliente</th><th>Unidades</th><th>Total</th><th></th></tr></thead><tbody>${[...sales].reverse().map(s=>{let pay=s.method==='Crédito'&&Number(s.creditAmount||0)>0?`Crédito · debe ${money(s.creditAmount)}${s.creditDueDate?' · vence '+new Date(s.creditDueDate+'T23:59:59').toLocaleDateString('es-PE'):''}`:s.method==='Mixto'&&Number(s.creditAmount||0)>0?`Mixto · crédito ${money(s.creditAmount)}`:s.method;return `<tr><td>${new Date(s.date).toLocaleString('es-PE')}</td><td>${esc(s.receipt)}</td><td>${esc(pay)}</td><td>${esc(s.customerName||'-')}</td><td>${s.units}</td><td>${money(s.total)}</td><td><button onclick="ticket('${s.id}')">🧾</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="panel">Todavía no hay ventas.</div>'}
function cashOpen(){return cash.find(x=>x.type==='OPEN'&&!x.closed)}
function currentCashEntries(){let open=cashOpen();if(!open)return[];let start=new Date(open.date);return cash.filter(x=>!x.closed&&new Date(x.date)>=start)}
function physicalCashExpected(){return currentCashEntries().reduce((s,x)=>{if(x.type==='OPEN'||x.type==='IN')return s+Number(x.amount||0);if(x.type==='OUT')return s-Number(x.amount||0);if(x.type==='CREDIT_PAYMENT')return s+Number(x.cashAmount||0);if(x.type==='SALE')return s+Number(x.cashAmount??x.amount??0);return s},0)}
function paymentTotalsSince(start){let out={cash:0,yape:0,card:0,credit:0,creditCollectionsYape:0,creditCollectionsCard:0,creditCollectionsCash:0};sales.filter(s=>new Date(s.date)>=start).forEach(s=>{let b=s.paymentBreakdown;if(b){out.cash+=Number(b.cash||0);out.yape+=Number(b.digital||0);out.card+=Number(b.card||0);out.credit+=Number(b.credit||s.creditAmount||0)}else if(s.method==='Efectivo')out.cash+=Number(s.total||0);else if(s.method==='Yape / Plin'||s.method==='Yape'||s.method==='Plin')out.yape+=Number(s.total||0);else if(s.method==='Tarjeta')out.card+=Number(s.total||0);else if(s.method==='Crédito')out.credit+=Number(s.creditAmount!=null?s.creditAmount:s.total||0)});cash.filter(x=>x.type==='CREDIT_PAYMENT'&&!x.initial&&new Date(x.date)>=start).forEach(x=>{let b=x.paymentBreakdown||{};out.creditCollectionsCash+=Number(x.cashAmount??b.cash??0);out.creditCollectionsYape+=Number(b.digital??(x.method==='Yape / Plin'?x.digitalAmount||x.amount||0:0));out.creditCollectionsCard+=Number(b.card??(x.method==='Tarjeta'?x.digitalAmount||x.amount||0:0))});return out}
function digitalSalesTotal(){let open=cashOpen();if(!open)return 0;let t=paymentTotalsSince(new Date(open.date));return t.yape+t.card+t.creditCollectionsYape+t.creditCollectionsCard}
function renderCash(){let open=cashOpen(),expected=physicalCashExpected(),digital=digitalSalesTotal();$('cashStatus').textContent=open?'ABIERTA':'CERRADA';$('cashBalance').textContent=money(expected);if($('digitalBalance'))$('digitalBalance').textContent=money(digital);$('openCash').disabled=!!open;$('cashIn').disabled=!open;$('cashOut').disabled=!open;$('closeCash').disabled=!open;$('cashTable').innerHTML=cash.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Medio</th><th>Cliente</th><th>Detalle</th><th>Efectivo</th><th>Digital</th></tr></thead><tbody>${[...cash].reverse().map(x=>{let digital=Number(x.digitalAmount||0),eff=x.type==='SALE'?(x.cashAmount??x.amount):x.type==='CREDIT_PAYMENT'?Number(x.cashAmount||0):['IN','OUT','OPEN','CLOSE'].includes(x.type)?Number(x.amount||0):0;return `<tr><td>${new Date(x.date).toLocaleString('es-PE')}</td><td>${esc(x.type)}</td><td>${esc(x.method||'-')}</td><td>${esc(x.customerName||'')}</td><td>${esc(x.note||'')}</td><td>${money(eff)}</td><td>${money(digital)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="panel">Sin movimientos.</div>'}
function productAnalysis(days=30){
  const now=new Date(), start=new Date(now); start.setHours(0,0,0,0); start.setDate(start.getDate()-(days-1));
  const end=new Date(now); end.setHours(23,59,59,999);
  const map={};
  sales.filter(s=>{const d=new Date(s.date);return d>=start&&d<=end;}).forEach(s=>{
    const discountRatio=s.subtotal>0?(Number(s.discount||0)/Number(s.subtotal||1)):0;
    (Array.isArray(s.items)?s.items:[]).forEach(i=>{
      if(i.free || !(i.id||i.productId))return;
      const itemId=i.id||i.productId;
      const p=products.find(x=>x.id===itemId); if(!p)return;
      const key=p.id; const qty=Number(i.qty)||0, gross=(Number(i.price)||0)*qty, discount=gross*discountRatio;
      if(!map[key])map[key]={p,qty:0,revenue:0,profit:0,last:null};
      map[key].qty+=qty; map[key].revenue+=Math.max(0,gross-discount); map[key].profit+=(Number(i.price||0)-Number(p.cost||i.cost||0))*qty-discount;
      const d=new Date(s.date); if(!map[key].last||d>map[key].last)map[key].last=d;
    });
  });
  const all=products.map(p=>map[p.id]||{p,qty:0,revenue:0,profit:0,last:null});
  const perDay=Math.max(1,days);
  all.forEach(x=>{
    x.daily=x.qty/perDay; x.coverage=x.daily>0?Number(x.p.stock||0)/x.daily:Infinity;
    x.capital=(Number(x.p.cost)||0)*(Number(x.p.stock)||0);
    x.daysNoSale=x.last?Math.max(0,Math.floor((now-x.last)/86400000)):'—';
    x.recommend=x.qty===0?(Number(x.p.stock||0)>0?'Revisar / no reponer':'Mantener'):(x.coverage<7||Number(x.p.stock||0)<=Number(x.p.min||0)?'Aumentar stock':x.coverage<=30?'Mantener':'Revisar / no reponer');
  });
  return {all,start,end};
}
function renderProductAnalysis(){
  const el=$('productAnalysis'); if(!el)return;
  const sel=$('analysisPeriod'); const days=sel&&sel.value==='7'?7:sel&&sel.value==='90'?90:sel&&sel.value==='365'?365:sel&&sel.value==='custom'?Math.max(1,Number($('analysisCustomDays')?.value)||30):30;
  const {all}=productAnalysis(days), sold=all.filter(x=>x.qty>0), top=[...sold].sort((a,b)=>b.qty-a.qty).slice(0,10), bottom=[...all].sort((a,b)=>a.qty-b.qty||b.capital-a.capital).slice(0,10);
  const fmt=x=>`${money(x.revenue)} · ${x.qty.toLocaleString('es-PE',{maximumFractionDigits:3})} uds.`;
  el.innerHTML=`<div class="analysis-summary"><div><small>Productos con ventas</small><b>${sold.length}</b></div><div><small>Unidades vendidas</small><b>${sold.reduce((a,x)=>a+x.qty,0).toLocaleString('es-PE',{maximumFractionDigits:3})}</b></div><div><small>Ganancia estimada</small><b>${money(sold.reduce((a,x)=>a+x.profit,0))}</b></div></div>
  <div class="analysis-grid"><div class="panel"><h3>🔥 Más vendidos</h3>${top.length?top.map((x,i)=>`<div class="analysis-row"><span><b>#${i+1} ${esc(x.p.name)}</b><small>${fmt(x)} · Stock ${x.p.stock}</small></span><em class="tag good">${esc(x.recommend)}</em></div>`).join(''):'<p>Sin ventas en este período.</p>'}</div>
  <div class="panel"><h3>🐢 Menos vendidos / revisar</h3>${bottom.length?bottom.map(x=>`<div class="analysis-row"><span><b>${esc(x.p.name)}</b><small>${fmt(x)} · Stock ${x.p.stock} · Capital ${money(x.capital)} · Última venta: ${x.daysNoSale==='—'?'Nunca':x.daysNoSale===0?'Hoy':`hace ${x.daysNoSale} días`}</small></span><em class="tag ${x.recommend.startsWith('Aumentar')?'good':x.recommend.startsWith('Mantener')?'warn':'bad'}">${esc(x.recommend)}</em></div>`).join(''):'<p>No hay productos.</p>'}</div></div>`;
}
function reports(){let d=new Date();d.setHours(0,0,0,0);let today=sales.filter(s=>new Date(s.date)>=d),tot=today.reduce((s,x)=>s+x.total,0);$('todaySales').textContent=money(tot);$('avgTicket').textContent=money(today.length?tot/today.length:0);$('unitsSold').textContent=today.reduce((s,x)=>s+x.units,0);let pm={};today.forEach(s=>(Array.isArray(s.items)?s.items:[]).forEach(i=>pm[i.name]=(pm[i.name]||0)+Number(i.qty||0)));let top=Object.entries(pm).sort((a,b)=>b[1]-a[1]).slice(0,8);$('topProducts').innerHTML=top.map(([n,q])=>`<p><b>${esc(n)}</b> · ${q} uds.</p>`).join('')||'<p>Sin ventas hoy.</p>';let lows=products.filter(p=>p.stock<=p.min);$('lowProducts').innerHTML=lows.map(p=>`<p><b>${esc(p.name)}</b> · ${p.stock} (mín. ${p.min})</p>`).join('')||'<p>Inventario saludable.</p>';let pt=paymentTotalsSince(d),pay={'Efectivo':pt.cash,'Yape / Plin':pt.yape,'Tarjeta':pt.card,'Crédito':pt.credit};$('paymentReport').innerHTML=Object.entries(pay).map(([k,v])=>`<p><b>${esc(k)}</b> · ${money(v)}</p>`).join('')+`<hr><p><b>Abonos en efectivo</b> · ${money(pt.creditCollectionsCash)}</p><p><b>Abonos Yape / Plin</b> · ${money(pt.creditCollectionsYape)}</p><p><b>Abonos Tarjeta</b> · ${money(pt.creditCollectionsCard)}</p>`;renderProductAnalysis()}

function renderAll(){renderCats();renderProducts();renderCart();renderProductTable();renderInventory();renderCustomers();renderPurchases();renderSales();renderCash();reports();if($('businessName'))$('businessName').value=cfg.name||'BMA MINIMARKET';if($('businessAddress'))$('businessAddress').value=cfg.address||'';if($('businessPhone'))$('businessPhone').value=cfg.phone||'';if($('currency'))$('currency').value=cfg.currency||'S/';customerOptions($('saleCustomer')?.value||'')}
function navigate(page){document.querySelectorAll('.page,.nav').forEach(x=>x.classList.remove('active'));$(page).classList.add('active');document.querySelector(`[data-page="${page}"]`).classList.add('active');renderAll()}
function openProduct(p=null){editingProduct=p?.id||null;$('productDialogTitle').textContent=p?'Editar producto':'Nuevo producto';$('productForm').reset();if(p)Object.entries(p).forEach(([k,v])=>{let el=$('productForm').elements[k];if(el)el.value=v});$('productDialog').showModal()}
function editProduct(id){openProduct(products.find(p=>p.id===id))}function deleteProduct(id){if(!confirm('¿Eliminar este producto?'))return;products=products.filter(p=>p.id!==id);persist();renderAll()}
function openCustomer(c=null){$('customerForm').reset();if(c)Object.entries(c).forEach(([k,v])=>{let el=$('customerForm').elements[k];if(el)el.value=v});$('customerDialog').showModal()}function editCustomer(id){openCustomer(customers.find(c=>c.id===id))}function deleteCustomer(id){let c=customers.find(c=>c.id===id);if(c?.balance>0)return alert('No puedes eliminar un cliente con deuda.');if(confirm('¿Eliminar cliente?')){customers=customers.filter(c=>c.id!==id);persist();renderAll()}}
function openCashDialog(action){cashAction=action;$('cashDialogTitle').textContent=action==='OPEN'?'Abrir caja':action==='IN'?'Ingreso de efectivo':'Egreso de efectivo';$('cashForm').reset();$('cashDialog').showModal()}
function openStock(action){stockAction=action;$('stockDialogTitle').textContent=action==='in'?'Entrada de mercancía':'Ajuste de inventario';$('stockProduct').innerHTML=products.map(p=>`<option value="${p.id}">${esc(p.name)} · stock ${p.stock}</option>`).join('');$('stockDialog').showModal()}
function openPurchase(){ $('purchaseProduct').innerHTML=products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');$('purchaseDialog').showModal() }
function ticket(id){const s=sales.find(x=>x.id===id);if(!s)return;const docType=esc(s.receipt||'Nota de venta');const rows=(Array.isArray(s.items)?s.items:[]).map(i=>`<tr><td>${esc(i.name)}${i.free?' · venta libre':''}<br><small>${i.qty} ${esc(i.unit||'Unidad')} × ${money(i.price)}</small></td><td style="text-align:right">${money(i.price*i.qty)}</td></tr>`).join('');$('printArea').innerHTML=`<div class="ticket-paper"><div class="center"><img class="receipt-logo" src="data:image/jpeg;base64," alt="BMA MINIMARKET"><h1>${esc(cfg.name)}</h1><b>${docType}</b><div>${new Date(s.date).toLocaleString('es-PE')}</div></div><div class="line"></div><div>Cliente: ${esc(s.customerName||'Mostrador')}</div><table>${rows}</table><div class="line"></div><table><tr><td>Subtotal</td><td style="text-align:right">${money(s.subtotal)}</td></tr><tr><td>Descuento</td><td style="text-align:right">-${money(s.discount)}</td></tr><tr class="total"><td>TOTAL</td><td style="text-align:right">${money(s.total)}</td></tr></table><div class="line"></div><div>Pago: ${esc(s.method)}</div>${s.paymentBreakdown?`<div>Efectivo: ${money(s.paymentBreakdown.cash||0)}</div><div>Yape / Plin: ${money(s.paymentBreakdown.digital||0)}</div><div>Tarjeta: ${money(s.paymentBreakdown.card||0)}</div>${Number(s.paymentBreakdown.credit||0)>0?`<div>Crédito: ${money(s.paymentBreakdown.credit)}</div>`:''}`:''}${s.creditAmount>0?`<div>Saldo pendiente: <b>${money(s.creditAmount)}</b>${s.creditDueDate?' · vence '+new Date(s.creditDueDate+'T23:59:59').toLocaleDateString('es-PE'):''}</div>`:''}<div class="center" style="margin-top:8px">Gracias por su compra</div></div>`;openPrintPreview()}
function openPrintPreview(){const d=$('printPreviewDialog');d.hidden=false;d.classList.add('show');document.body.classList.add('print-preview-open');setTimeout(()=>$('closePrintPreview2')?.focus(),0)}
function closePrintPreview(){const d=$('printPreviewDialog');d.classList.remove('show');d.hidden=true;document.body.classList.remove('print-preview-open','printing')}
function printReceipt(){const area=$('printArea');if(!area||!area.textContent.trim()){alert('Primero abre un comprobante para imprimir.');return}document.body.classList.add('printing');requestAnimationFrame(()=>requestAnimationFrame(()=>{try{window.print()}catch(e){alert('No se pudo abrir la impresión. Intenta nuevamente.')}}))}window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing');if($('printPreviewDialog')?.hidden===false){document.body.classList.add('print-preview-open')}});

function exportCSV(name,head,rows){let csv=[head,...rows].map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click()}

