const BMA_CLOUD={url:'https://lwmvnbwhvbbudujzlcta.supabase.co',key:'sb_publishable_p7e2Eu6wAA5fV5vHlyvjWg_3U-2oAou',store:'bma-main-store'};
let cloudTimer=null,cloudBusy=false;
const cloudHeaders=()=>({'apikey':BMA_CLOUD.key,'Authorization':'Bearer '+BMA_CLOUD.key,'Content-Type':'application/json'});
const cloudStamp=()=>localStorage.getItem('bma_cloud_updated_at')||'';
const setCloudStatus=t=>{const e=$('cloudTopStatus');if(e)e.textContent=t};
const cloudData=stamp=>({products,sales,cash,customers,purchases,moves,cfg,holds,version:4,updatedAt:stamp});
async function cloudGet(){try{const r=await fetch(BMA_CLOUD.url+'/rest/v1/bma_store?id=eq.'+encodeURIComponent(BMA_CLOUD.store)+'&select=data,updated_at',{headers:cloudHeaders()});if(!r.ok)throw Error(r.status);const a=await r.json();return a[0]||null}catch(e){console.warn(e);return null}}
async function cloudPut(){if(cloudBusy||!navigator.onLine)return false;cloudBusy=true;const stamp=new Date().toISOString();try{const r=await fetch(BMA_CLOUD.url+'/rest/v1/bma_store',{method:'POST',headers:{...cloudHeaders(),'Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({id:BMA_CLOUD.store,data:cloudData(stamp),updated_at:stamp})});if(!r.ok)throw Error(r.status);localStorage.setItem('bma_cloud_updated_at',stamp);setCloudStatus('☁ Sincronizado');return true}catch(e){console.warn(e);setCloudStatus('☁ Sin conexión');return false}finally{cloudBusy=false}}
function scheduleCloudSync(){clearTimeout(cloudTimer);cloudTimer=setTimeout(cloudPut,1200)}
async function cloudInitialSync(){setCloudStatus('☁ Conectando…');const r=await cloudGet();if(!r){setCloudStatus(navigator.onLine?'☁ Nube lista':'☁ Offline');return}const d=r.data||{},rs=String(d.updatedAt||r.updated_at||''),ls=cloudStamp();if(!Array.isArray(d.products)||!Array.isArray(d.sales)){setCloudStatus('☁ Datos remotos inválidos');return}if(!ls&&!products.length&&!sales.length&&!customers.length){products=d.products;sales=d.sales;cash=d.cash||[];customers=d.customers||[];purchases=d.purchases||[];moves=d.moves||[];cfg=d.cfg||cfg;holds=d.holds||[];saveAllLocal();localStorage.setItem('bma_cloud_updated_at',rs||new Date().toISOString());renderAll();setCloudStatus('☁ Sincronizado');return}if(rs&&ls&&rs>ls){products=d.products;sales=d.sales;cash=d.cash||[];customers=d.customers||[];purchases=d.purchases||[];moves=d.moves||[];cfg=d.cfg||cfg;holds=d.holds||[];saveAllLocal();localStorage.setItem('bma_cloud_updated_at',rs);renderAll();setCloudStatus('☁ Sincronizado')}else{setCloudStatus('☁ Datos locales protegidos');scheduleCloudSync()}}
const saveAllLocal=()=>{save(K.products,products);save(K.sales,sales);save(K.cash,cash);save(K.customers,customers);save(K.purchases,purchases);save(K.moves,moves);save(K.cfg,cfg);save(K.holds,holds)};


