// Lector USB/Bluetooth: funciona como teclado y normalmente termina con Enter.
let usbScanBuffer='',usbScanStarted=0,usbScanTimer=null;
function processUsbBarcode(code){
  code=String(code||'').trim();
  if(code.length<3)return false;
  let p=products.find(x=>String(x.code||'').trim()===code);
  if(!p){
    $('search').value=code;
    renderProducts();
    return false;
  }
  $('search').value=code;
  add(p.id);
  renderProducts();
  return true;
}
document.addEventListener('keydown',e=>{
  if(e.ctrlKey||e.altKey||e.metaKey)return;
  const now=Date.now();
  if(e.key==='Enter'){
    if(usbScanBuffer.length>=3 && now-usbScanStarted<1500){
      e.preventDefault();
      e.stopPropagation();
      processUsbBarcode(usbScanBuffer);
    }
    usbScanBuffer='';usbScanStarted=0;
    if(usbScanTimer)clearTimeout(usbScanTimer);
    return;
  }
  if(e.key.length!==1 || !/[0-9A-Za-z]/.test(e.key))return;
  if(!usbScanBuffer || now-usbScanStarted>1500){usbScanBuffer=e.key;usbScanStarted=now}
  else usbScanBuffer+=e.key;
  if(usbScanTimer)clearTimeout(usbScanTimer);
  usbScanTimer=setTimeout(()=>{usbScanBuffer='';usbScanStarted=0},180);
},{capture:true});
