$('creditPaymentForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),c=customers.find(x=>x.id===f.get('customerId'));if(!c)return;let debt=customerDebt(c),method=f.get('method'),amount=Number(f.get('amount')||0);if(!(amount>0)||amount>debt)return alert('El abono debe ser mayor a 0 y no superar la deuda.');let cashAmount=0,digitalAmount=0,breakdown;if(method==='Efectivo')cashAmount=amount;else if(method==='Yape / Plin')digitalAmount=amount;else if(method==='Tarjeta')digitalAmount=amount;else{let mc=Number(f.get('mixCash')||0),my=Number(f.get('mixDigital')||0),mt=Number(f.get('mixCard')||0);if(Math.abs(mc+my+mt-amount)>0.009)return alert('El abono mixto debe sumar exactamente el monto.');cashAmount=mc;digitalAmount=my+mt;breakdown={cash:mc,digital:my,card:mt}}if(!breakdown)breakdown={cash:cashAmount,digital:method==='Yape / Plin'?digitalAmount:0,card:method==='Tarjeta'?digitalAmount:0};cash.push({id:uid(),date:new Date().toISOString(),type:'CREDIT_PAYMENT',amount,cashAmount,digitalAmount,method,paymentBreakdown:breakdown,customerId:c.id,customerName:c.name,note:`Abono · ${c.name}`,closed:false});c.balance=Math.max(0,debt-amount);persist();$('creditPaymentDialog').close();renderAll();viewCustomer(c.id)};
function viewCustomer(id){let c=customers.find(x=>x.id===id);if(!c)return;let debt=customerDebt(c),limit=Number(c.limit||0),available=limit?Math.max(0,limit-debt):null,rows=customerCreditHistory(c);$('customerAccountTitle').textContent=`Cuenta de ${c.name}`;$('customerAccountSummary').innerHTML=`<div class="account-cards"><div><small>Debe</small><b class="${debt>0?'low':''}">${money(debt)}</b></div><div><small>Abonos</small><b>${money(customerPayments(c))}</b></div><div><small>Límite</small><b>${limit?money(limit):'Sin límite'}</b></div><div><small>Disponible</small><b>${available===null?'—':money(available)}</b></div></div>`;$('customerAccountTable').innerHTML=rows.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Fecha</th><th>Movimiento</th><th>Detalle</th><th>Monto</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(r.date).toLocaleString('es-PE')}</td><td>${esc(r.type)}</td><td>${esc(r.detail)}</td><td class="${r.amount<0?'paid':'debt'}">${r.amount<0?'−':'+'}${money(Math.abs(r.amount))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Sin movimientos de crédito.</p>';$('customerAccountDialog').showModal()}


